    }
    .register_btn{
        margin-top: 1vw;
        background-color: #447dd4 !important;
        width: 80%;
        border-radius: 20px;
        margin-left: 3vw;
        height: 100%;
        color: white !important;
    }
    .student{
        margin-left: 2vw;
        text-decoration:none !important;
        color: #447dd4 !important;
    }
    .company{
        text-decoration:none !important;
